const MODE = { plugin: 'sticky-mode', key: 'mode' }
const NOTICE = { plugin: 'sticky-mode', key: 'notice' }
const OFFER = { plugin: 'sticky-mode', key: 'offer' }
const COMMAND = 'mode'
const MUTED = '#8a8a8a'
const ICON = `<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="${MUTED}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 14a1 1 0 0 1-.78-1.63l9.9-10.2a.5.5 0 0 1 .86.46l-1.92 6.02A1 1 0 0 0 13 10h7a1 1 0 0 1 .78 1.63l-9.9 10.2a.5.5 0 0 1-.86-.46l1.92-6.02A1 1 0 0 0 11 14z"/></svg>`
const SUGGESTION_LIMIT = 8

export function register(on) {
  on('session.start', async ($, e, next) => {
    const result = await next(e)
    await restoreMode($)
    try {
      await $.command.register({
        name: COMMAND,
        description: 'Keep a skill on for the whole session',
        argumentHint: '<skill> | off',
      })
    } catch (error) {
      $.ui.toast('sticky-mode could not add /' + COMMAND + ': ' + error.message)
    }
    return result
  })

  on('command.run', { command: COMMAND }, async ($, e) => {
    const requested = e.args.trim().replace(/^\//, '')
    const { value: current = null } = await $.state.get(MODE)

    if (requested === '') {
      return {
        text: current
          ? `Mode on: /${current.skill}. Run /mode off to exit.`
          : 'No mode is on. Run /mode <skill>. In the terminal you can also pick a skill from the / menu and press Option+Enter.',
      }
    }

    if (requested === 'off') {
      if (!current) return { text: 'No mode is on.' }
      await saveMode($, null)
      return { text: `Mode off: /${current.skill}.`, context: [offNotice(current)] }
    }

    const lookup = await resolveSkill($, requested)
    if (lookup.kind === 'ambiguous') {
      return { text: `Several skills are named ${requested}: ${lookup.names.map((n) => '/' + n).join(', ')}. Run /mode with the full name of one.` }
    }
    if (lookup.kind === 'missing') {
      const hint = lookup.suggestions.length ? ` Did you mean ${lookup.suggestions.map((n) => '/' + n).join(', ')}?` : ''
      return { text: `No skill named /${requested} was found.${hint}` }
    }
    const mode = await engage($, lookup, false)
    return { text: `Mode on: /${mode.skill}. It stays on every turn until /mode off.`, context: [fullText(mode)] }
  })

  on('command.run', async ($, e, next) => {
    const result = await next(e)
    const lookup = await resolveSkill($, e.command)
    if (lookup.kind !== 'found') return result
    const { value: mode = null } = await $.state.get(MODE)
    if (mode?.skill !== lookup.name) await $.state.set(OFFER, lookup.name)
    return result
  })

  on('prompt.edit', async ($, e, next) => {
    if (e.inputText !== '\n') return next(e)
    const picked = e.text.match(/^\/([\w:.-]+)\s*$/)
    if (!picked || picked[1] === COMMAND) return next(e)
    const lookup = await resolveSkill($, picked[1])
    if (lookup.kind !== 'found') return next(e)
    await engage($, lookup, true)
    return { text: '', cursor: 0 }
  })

  on('session.compact', async ($, e, next) => {
    const result = await next(e)
    const { value: mode = null } = await $.state.get(MODE)
    if (mode && !result?.skip) await $.state.set(MODE, { ...mode, needsFullText: true })
    return result
  })

  on('prompt.submit', async ($, e, next) => {
    const { value: mode = null } = await $.state.get(MODE)
    const { value: notice = null } = await $.state.get(NOTICE)
    if (!e.text.startsWith('/')) await $.state.set(OFFER, null)
    const notes = []
    if (notice) {
      notes.push(notice)
      await $.state.set(NOTICE, null)
    }
    if (mode) {
      if (mode.needsFullText) await $.state.set(MODE, { ...mode, needsFullText: false })
      notes.push(mode.needsFullText ? fullText(mode) : reminder(mode))
    }
    if (notes.length === 0) return next(e)
    return next({ ...e, context: [...(e.context ?? []), ...notes] })
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const { value: mode = null } = await $.state.get(MODE)
    const { value: offer = null } = await $.state.get(OFFER)
    if ((!mode && !offer) || e.props.hasSurvey) return next(e)
    const { Box, Text, Button, Svg } = $.ui.resolve(e)
    const icon = e.surface === 'desktop' ? [Svg({ source: ICON, alt: 'Session mode', width: 14, height: 14 })] : []
    const rows = []

    if (offer) {
      rows.push(Box({
        flexDirection: 'row',
        gap: 1,
        paddingX: 1,
        children: [
          ...icon,
          Text({ color: MUTED, children: `${shortName(offer)} ran.` }),
          Button({
            key: 'keep-on',
            label: 'Keep on',
            variant: 'primary',
            onPress: async () => {
              const lookup = await resolveSkill($, offer)
              await $.state.set(OFFER, null)
              if (lookup.kind !== 'found') return
              await engage($, lookup, false)
              await $.state.set(NOTICE, keptNotice(lookup.name))
            },
          }),
          Button({ key: 'dismiss-offer', label: 'Dismiss', role: 'dismiss', dimColor: true, onPress: () => $.state.set(OFFER, null) }),
        ],
      }))
    }

    if (mode) rows.push(Box({
      flexDirection: 'row',
      gap: 1,
      paddingX: 1,
      children: [
        ...icon,
        Text({ color: MUTED, bold: true, children: shortName(mode.skill) }),
        Button({
          key: 'exit-mode',
          label: 'Exit mode',
          role: 'dismiss',
          dimColor: true,
          onPress: async () => {
            await saveMode($, null)
            await $.state.set(NOTICE, offNotice(mode))
          },
        }),
      ],
    }))

    const below = await next(e)
    if (below) rows.push(below)
    return rows.length === 1 ? rows[0] : Box({ flexDirection: 'column', children: rows })
  })
}

async function engage($, skill, needsFullText) {
  const mode = { skill: skill.name, text: skill.text, needsFullText }
  await saveMode($, mode)
  await $.state.set(NOTICE, null)
  return mode
}

async function saveMode($, mode) {
  await $.state.set(MODE, mode)
  const key = 'mode:' + (await $.session.id())
  if (mode) await $.store.set(key, mode.skill)
  else await $.store.delete(key)
}

async function restoreMode($) {
  const { value: current = null } = await $.state.get(MODE)
  if (current) return
  const saved = await $.store.get('mode:' + (await $.session.id()))
  if (typeof saved !== 'string') return
  const lookup = await resolveSkill($, saved)
  if (lookup.kind !== 'found') return
  await $.state.set(MODE, { skill: lookup.name, text: lookup.text, needsFullText: true })
}

async function resolveSkill($, requested) {
  const commands = (await $.command.list()).filter((c) => c.source === 'plugin' || c.source === 'user')
  const candidates = requested.includes(':')
    ? [requested]
    : commands.map((c) => c.name).filter((name) => name === requested || name.endsWith(':' + requested))

  const found = []
  for (const name of candidates) {
    const location = await findSkill($, name)
    if (location) found.push({ name, location })
  }

  if (found.length === 1) {
    const { name, location } = found[0]
    return { kind: 'found', name, text: await readSkill($, location) }
  }
  if (found.length > 1) return { kind: 'ambiguous', names: found.map((f) => f.name) }

  const ranked = commands
    .map(({ name }) => ({ name, rank: matchRank(name, requested) }))
    .filter((c) => c.rank !== null)
    .sort((a, b) => a.rank - b.rank || a.name.length - b.name.length)
  const suggestions = []
  for (const { name } of ranked) {
    if (suggestions.length === SUGGESTION_LIMIT) break
    if (await findSkill($, name)) suggestions.push(name)
  }
  return { kind: 'missing', suggestions }
}

function matchRank(name, query) {
  const haystack = shortName(name).toLowerCase()
  const needle = shortName(query).toLowerCase()
  if (haystack.includes(needle)) return 0
  let best = null
  for (let start = haystack.indexOf(needle[0]); start !== -1; start = haystack.indexOf(needle[0], start + 1)) {
    let at = 0
    let end = start
    for (; end < haystack.length && at < needle.length; end += 1) if (haystack[end] === needle[at]) at += 1
    const span = end - start
    if (at === needle.length && span <= needle.length * 2 && (best === null || span < best)) best = span
  }
  return best
}

function fullText(mode) {
  return [
    `# Session mode: /${mode.skill}`,
    `The user turned on the /${mode.skill} skill as a session mode. Follow it on every turn until the user runs /mode off. Do not invoke the skill again; its full text is below.`,
    '',
    mode.text,
  ].join('\n')
}

function shortName(skill) {
  return skill.split(':').pop()
}

function keptNotice(skill) {
  return `# Session mode: /${skill}\nThe user turned the /${skill} skill you just ran into a session mode. Keep following its instructions, given above, on every turn until the user runs /mode off.`
}

function offNotice(mode) {
  return `The user turned off the /${mode.skill} session mode. Stop following its instructions from now on.`
}

function reminder(mode) {
  return `Session mode /${mode.skill} is still on. Keep following its instructions, given in full earlier in this conversation.`
}

async function readSkill($, location) {
  const raw = await $.fs.read(location.file)
  return substitute(withoutFrontmatter(raw), location.vars).trim()
}

async function findSkill($, name) {
  const home = await $.env.get('HOME')
  if (name.includes(':')) {
    const [plugin, skill] = name.split(':')
    return findPluginSkill($, home, plugin, skill)
  }

  const cwd = await $.session.cwd()
  for (const root of [`${cwd}/.claude/skills`, `${home}/.claude/skills`]) {
    const dir = `${root}/${name}`
    if (await $.fs.exists(`${dir}/SKILL.md`)) {
      return { file: `${dir}/SKILL.md`, vars: { CLAUDE_SKILL_DIR: dir } }
    }
  }
  return null
}

async function findPluginSkill($, home, plugin, skill) {
  const registry = JSON.parse(await $.fs.read(`${home}/.claude/plugins/installed_plugins.json`))
  const id = Object.keys(registry.plugins).find((key) => key.split('@')[0] === plugin)
  if (!id) return null

  const root = registry.plugins[id][0].installPath
  const dir = `${root}/skills/${skill}`
  if (!(await $.fs.exists(`${dir}/SKILL.md`))) return null

  const marketplace = id.split('@')[1]
  return {
    file: `${dir}/SKILL.md`,
    vars: {
      CLAUDE_PLUGIN_ROOT: root,
      CLAUDE_SKILL_DIR: dir,
      CLAUDE_PLUGIN_DATA: `${home}/.claude/plugins/data/${plugin}-${marketplace}`,
    },
  }
}

function withoutFrontmatter(markdown) {
  return markdown.replace(/^---\n[\s\S]*?\n---\n/, '')
}

function substitute(text, vars) {
  return text.replace(/\$\{(CLAUDE_[A-Z_]+)\}/g, (match, key) => vars[key] ?? match)
}

